// The rust backend (docs/spec/fsm.md, B-4 and B-6; docs/plans/fsm-v1/plan.md, C-2): the generated files of the rust package
// `src/` and the native vector module `tests/conformance/vectors.rs`. It takes the IRs of the machines (normalize.mjs), in definition order,
// and the lock, and returns the text of every file; it writes nothing. The output is deterministic: declaration order, four
// spaces of indentation and a final line break. The core imports nothing from node:, and the generated code has no runtime
// dependency.
//
// The language difference of this kind is the vector module: `tests/conformance/vectors.rs` is one #[test] per case in the module of the
// conformance test crate (tests/conformance/main.rs), which calls the check functions of that crate (check_value, check_slice,
// check_result and check_persist). The machine functions return Result with fsm::Error, so a case compares the value or the
// error code of the function it names.

import { forKind } from '../core/vectors.mjs';

const SHARED = 'fsm';
const CRATE = 'fsm_rust';
const KIND = 'rust';

/** The variant name of a key: the pascal notation of B-6. Keys match ^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$, so this is one-to-one. */
const pascal = key => key.split('_').map(word => word[0].toUpperCase() + word.slice(1)).join('');

/** The first line of a generated file (docs/spec/fsm.md, B-6). */
const header = from => `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`;

/** The text of a list of lines: each line ends with a line break. */
const text = lines => `${lines.join('\n')}\n`;

/** The shared module: the error codes of B-4, B-5 and B-6 and the Error of every machine function. */
const FSM_RS = text([
  header(SHARED),
  '',
  '/// The error codes that the functions of every machine return (docs/spec/fsm.md, B-4 and B-6).',
  '#[derive(Debug, Clone, Copy, PartialEq, Eq)]',
  'pub enum Code {',
  '    /// E_CONFLICT: the stored state is neither the expected state nor the target.',
  '    Conflict,',
  '    /// E_INVALID_TRANSITION: the event has no edge from the expected state.',
  '    InvalidTransition,',
  '    /// E_UNKNOWN_CODE: the value is no state of the machine.',
  '    UnknownCode,',
  '    /// E_RESERVED_CODE: the code is reserved and is no state of the machine.',
  '    ReservedCode,',
  '}',
  '',
  'impl Code {',
  '    /// The code as docs/spec/fsm.md writes it, such as E_CONFLICT.',
  '    pub fn as_str(self) -> &\'static str {',
  '        match self {',
  '            Code::Conflict => "E_CONFLICT",',
  '            Code::InvalidTransition => "E_INVALID_TRANSITION",',
  '            Code::UnknownCode => "E_UNKNOWN_CODE",',
  '            Code::ReservedCode => "E_RESERVED_CODE",',
  '        }',
  '    }',
  '}',
  '',
  '/// The error of a machine function. The fields hold the codes of the arguments that failed (an event by its declaration index); the others are None.',
  '#[derive(Debug, Clone, PartialEq, Eq)]',
  'pub struct Error {',
  '    /// The error code.',
  '    pub code: Code,',
  '    /// The message, which names the machine.',
  '    pub message: String,',
  '    /// The expected state, by its code.',
  '    pub expected: Option<i32>,',
  '    /// The stored state, by its code.',
  '    pub actual: Option<i32>,',
  '    /// The event, by its declaration index.',
  '    pub event: Option<i32>,',
  '}',
  '',
  'impl Error {',
  '    /// An error with its code and message and no field.',
  '    pub fn new(code: Code, message: impl Into<String>) -> Error {',
  '        Error { code, message: message.into(), expected: None, actual: None, event: None }',
  '    }',
  '}',
  '',
  'impl std::fmt::Display for Error {',
  '    fn fmt(&self, f: &mut std::fmt::Formatter<\'_>) -> std::fmt::Result {',
  '        write!(f, "{}: {}", self.code.as_str(), self.message)',
  '    }',
  '}',
  '',
  'impl std::error::Error for Error {}',
]);

/** The machine module of `ir` with its reserved codes from `lock`: the states, events, Step and functions of B-6, in that order. */
function machineRs(ir, lock) {
  const { machine, initial, states, events, transitions } = ir;
  const reserved = [...lock[machine].reserved].sort((a, b) => a - b);
  const stateOf = key => `State::${pascal(key)}`;
  const eventOf = key => `Event::${pascal(key)}`;
  const outgoing = state => events.filter(event => transitions.some(item => item.state === state.key && item.event === event.key));
  const toOf = (state, event) => transitions.find(item => item.state === state && item.event === event).to;
  const edges = state => outgoing(state).map(event => [event, toOf(state.key, event.key)]);
  const arms = states.flatMap(state => edges(state).map(([event, to]) => `        (${stateOf(state.key)}, ${eventOf(event.key)}) => Ok(${stateOf(to)}),`));
  const lines = [
    header(machine),
    '',
    'use crate::fsm::{Code, Error};',
    '',
    `/// The states of ${machine}: the value of each member is its code.`,
    '#[repr(i32)]',
    '#[derive(Debug, Clone, Copy, PartialEq, Eq)]',
    'pub enum State {',
    ...states.map(state => `    ${pascal(state.key)} = ${state.code},`),
    '}',
    '',
    `/// The events of ${machine}: the value of each member is its position in the declaration, from 1.`,
    // A zero-variant enum takes no representation (rustc E0084), so a machine without events has none.
    ...(events.length === 0 ? [] : ['#[repr(i32)]']),
    '#[derive(Debug, Clone, Copy, PartialEq, Eq)]',
    'pub enum Event {',
    ...events.map((event, index) => `    ${pascal(event.key)} = ${index + 1},`),
    '}',
    '',
    '/// The result of apply: the state that the event leads to, and whether the stored state changed.',
    '#[derive(Debug, Clone, Copy, PartialEq, Eq)]',
    'pub struct Step {',
    '    pub to: State,',
    '    pub changed: bool,',
    '}',
    '',
    `/// The initial state of ${machine}.`,
    'pub fn initial() -> State {',
    `    State::${pascal(initial)}`,
    '}',
    '',
    '/// The code of a state, which is its value.',
    'pub fn code(state: State) -> i32 {',
    '    state as i32',
    '}',
    '',
    '/// The key of a state.',
    'pub fn key(state: State) -> &\'static str {',
    '    match state {',
    ...states.map(state => `        ${stateOf(state.key)} => "${state.key}",`),
    '    }',
    '}',
    '',
    '/// The state of a code: E_RESERVED_CODE for a reserved code, E_UNKNOWN_CODE for any other value.',
    'pub fn from_code(value: i64) -> Result<State, Error> {',
    '    match value {',
    ...states.map(state => `        ${state.code} => Ok(${stateOf(state.key)}),`),
    ...reserved.map(item => `        ${item} => Err(Error::new(Code::ReservedCode, "${machine}: code ${item} is reserved and is no state of ${machine}")),`),
    `        _ => Err(Error::new(Code::UnknownCode, format!("${machine}: {value} is not a state of ${machine}"))),`,
    '    }',
    '}',
    '',
    '/// Whether a state is final.',
    'pub fn is_final(state: State) -> bool {',
    '    match state {',
    ...states.map(state => `        ${stateOf(state.key)} => ${state.final},`),
    '    }',
    '}',
    '',
    '/// The events that have an edge from a state, in declaration order.',
    'pub fn events_from(state: State) -> &\'static [Event] {',
    '    match state {',
    ...states.map(state => {
      const list = outgoing(state).map(event => eventOf(event.key));
      return `        ${stateOf(state.key)} => &[${list.join(', ')}],`;
    }),
    '    }',
    '}',
    '',
    '/// The error of an event that has no edge from the state.',
    'fn invalid_transition(expected: State, event: Event) -> Error {',
    '    Error {',
    '        expected: Some(code(expected)),',
    '        event: Some(event as i32),',
    `        ..Error::new(Code::InvalidTransition, format!("${machine}: the event {} has no edge from {}", event as i32, key(expected)))`,
    '    }',
    '}',
    '',
    '/// The state that an event leads to from the expected state; E_INVALID_TRANSITION when the event has no edge from it.',
    'pub fn target(expected: State, event: Event) -> Result<State, Error> {',
    // A machine without edges has no arm but the error, and a match of one wildcard arm fails clippy (match_single_binding).
    ...(arms.length === 0
      ? ['    Err(invalid_transition(expected, event))']
      : ['    match (expected, event) {', ...arms, '        _ => Err(invalid_transition(expected, event)),', '    }']),
    '}',
    '',
    '/// Applies an event that the observed state expected leads to, when the stored state is actual (docs/spec/fsm.md, B-4).',
    'pub fn apply(expected: State, event: Event, actual: State) -> Result<Step, Error> {',
    '    let to = target(expected, event)?;',
    '    if actual == expected {',
    '        return Ok(Step { to, changed: true });',
    '    }',
    '    if actual == to {',
    '        return Ok(Step { to, changed: false });',
    '    }',
    '    Err(Error {',
    '        expected: Some(code(expected)),',
    '        actual: Some(code(actual)),',
    '        event: Some(event as i32),',
    `        ..Error::new(Code::Conflict, format!("${machine}: the stored state {} is neither {} nor {}", key(actual), key(expected), key(to)))`,
    '    })',
    '}',
  ];
  return text(lines);
}

/** The module file of the crate root: one module per machine in definition order, then the shared module. */
function libRs(irs) {
  return text([
    header(SHARED),
    '',
    ...irs.map(ir => `pub mod ${ir.machine};`),
    `pub mod ${SHARED};`,
  ]);
}

/**
 * The files of the rust package `src/` for the machines `irs` (their IRs in definition order) and the lock: `<machine>.rs` per
 * machine, then `fsm.rs` and `lib.rs`. Each file is { path, content }.
 */
export function files(irs, lock) {
  const out = [];
  for (const ir of irs) {
    if (!Object.hasOwn(lock, ir.machine)) throw new Error(`rust: the lock has no entry for machine ${ir.machine}`);
    out.push({ path: `${ir.machine}.rs`, content: machineRs(ir, lock) });
  }
  out.push({ path: `${SHARED}.rs`, content: FSM_RS });
  out.push({ path: 'lib.rs', content: libRs(irs) });
  return out;
}

/** The expression of a state of `machine` by its key, such as order::State::Draft. */
const stateExpr = (machine, key) => `${machine}::State::${pascal(key)}`;

/** The expression of an event of `machine` by its key, such as order::Event::Next. */
const eventExpr = (machine, key) => `${machine}::Event::${pascal(key)}`;

/** The Code variant of an error code of docs/spec/fsm.md, such as E_CONFLICT to Conflict. */
function errorVariant(error) {
  const variant = {
    E_CONFLICT: 'Conflict',
    E_INVALID_TRANSITION: 'InvalidTransition',
    E_UNKNOWN_CODE: 'UnknownCode',
    E_RESERVED_CODE: 'ReservedCode',
  }[error];
  if (variant === undefined) throw new Error(`rust: ${error} is no error code of fsm.Error`);
  return variant;
}

/** The Rust literal of the expected error of an error case: its code and the fields of fsm.Error (null is None, docs/spec/fsm.md, B-6). */
function expectedOf(expect) {
  const option = value => (value === null ? 'None' : `Some(${value})`);
  return `crate::Expected { code: Code::${errorVariant(expect.error)}, expected: ${option(expect.expected)}, actual: ${option(expect.actual)}, event: ${option(expect.event)} }`;
}

/** The body lines of the test of one vector case `c` of `machine`: the check of its feature with the expected value or error code. */
function bodyOf(machine, c) {
  const state = key => stateExpr(machine, key);
  const event = key => eventExpr(machine, key);
  // The raw code of a state, for the persist cases: the code function of the machine on the state.
  const code = key => `${machine}::code(${state(key)})`;
  switch (c.feature) {
    case 'initial':
      return [`crate::check_value(${machine}::initial(), ${state(c.expect.state)});`];
    case 'code':
      return [`crate::check_value(${machine}::code(${state(c.state)}), ${c.expect});`];
    case 'key':
      return [`crate::check_result(${machine}::from_code(${c.code}).map(${machine}::key), Ok("${c.expect}"));`];
    case 'from_code':
      return c.expect.error !== undefined
        ? [`crate::check_result(${machine}::from_code(${c.input}), Err(${expectedOf(c.expect)}));`]
        : [`crate::check_result(${machine}::from_code(${c.input}), Ok(${state(c.expect.state)}));`];
    case 'is_final':
      return [`crate::check_value(${machine}::is_final(${state(c.state)}), ${c.expect});`];
    case 'events_from':
      return [`crate::check_slice(${machine}::events_from(${state(c.state)}), &[${c.expect.map(event).join(', ')}]);`];
    case 'target':
      return c.expect.error !== undefined
        ? [`crate::check_result(${machine}::target(${state(c.state)}, ${event(c.event)}), Err(${expectedOf(c.expect)}));`]
        : [`crate::check_result(${machine}::target(${state(c.state)}, ${event(c.event)}), Ok(${state(c.expect.state)}));`];
    case 'apply': {
      const call = `${machine}::apply(${state(c.expected)}, ${event(c.event)}, ${state(c.actual)})`;
      return c.expect.error !== undefined
        ? [`crate::check_result(${call}, Err(${expectedOf(c.expect)}));`]
        : [`crate::check_result(${call}, Ok(${machine}::Step { to: ${state(c.expect.to)}, changed: ${c.expect.changed} }));`];
    }
    case 'persist': {
      const outcome = c.expect.error !== undefined
        ? `Err(${expectedOf(c.expect)})`
        : `Ok((${code(c.expect.stored_after)}, ${c.expect.changed}))`;
      return [
        'crate::check_persist(',
        `    ${code(c.stored)},`,
        '    |stored| {',
        `        let actual = ${machine}::from_code(stored)?;`,
        `        let step = ${machine}::apply(${state(c.expected)}, ${event(c.event)}, actual)?;`,
        `        Ok((${machine}::code(step.to), step.changed))`,
        '    },',
        `    ${outcome},`,
        `    ${code(c.expect.stored_after)},`,
        ').await;',
      ];
    }
    default:
      throw new Error(`rust: no test for the feature ${c.feature}; the vectors and conformance.rs must agree`);
  }
}

/** The #[test] (or #[tokio::test] for a persist case) of one vector case `c` of `machine`, as lines. */
function testOf(machine, c) {
  const persist = c.feature === 'persist';
  return [
    persist ? '#[tokio::test]' : '#[test]',
    `${persist ? 'async ' : ''}fn ${c.name}() {`,
    ...bodyOf(machine, c).map(line => `    ${line}`),
    '}',
  ];
}

/**
 * The native vector module tests/conformance/vectors.rs of `vectorList`, the vectors of every machine in order: one #[test] per case that
 * calls the check functions of tests/conformance/main.rs (the crate root `crate::`). The persist cases are #[tokio::test].
 */
export function vectorsFile(list) {
  const vectorList = forKind(list, KIND);
  const tests = vectorList.flatMap(({ machine, cases }) => cases.map(c => testOf(machine, c)));
  return text([
    header(SHARED),
    '#![allow(non_snake_case, reason = "each test is named by the name of its case in the vector file, which the parity check of kit matches")]',
    '',
    `use ${CRATE}::fsm::Code;`,
    ...vectorList.map(({ machine }) => `use ${CRATE}::${machine};`),
    '',
    tests.map(lines => lines.join('\n')).join('\n\n'),
  ]);
}
